import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])

    if n == 2:
        print(-1)
        return

    if n % 2 == 1:
        c = list(range(n))
    else:
        k = n // 2
        c = list(range(n - 1)) + [3 * k - 1]

    L = max(c) + 1
    b = [L * (x + 1) for x in c]

    out = []
    for i in range(n):
        row = [str(b[i] + c[j]) for j in range(n)]
        out.append(" ".join(row))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
